import asyncio
import json
import threading
import time
import cv2

import rclpy
import websockets

from ultralytics import YOLO
from rclpy.node import Node
from std_msgs.msg import String


class Backend(Node):

    def __init__(self):
        super().__init__("backend")

        # ROS
        self.sensor_subscription = self.create_subscription(
            String,
            "/sensor_data",
            self.receive_sensor_data,
            10
        )

        self.command_publisher = self.create_publisher(
            String,
            "/robot_command",
            10
        )

        # WebSocket
        self.websocket_clients = set()
        self.loop = None

        # YOLO
        self.model = YOLO("best.pt")

        # Camera
        self.cap = cv2.VideoCapture(
            "/dev/video2",
            cv2.CAP_V4L2
        )

        self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)

        if not self.cap.isOpened():
            self.get_logger().error("Camera failed")
        else:
            self.get_logger().info("Camera started")

        self.running = True

        # Camera thread
        self.camera_thread = threading.Thread(
            target=self.camera_loop,
            daemon=True
        )

        self.camera_thread.start()

        self.get_logger().info("Backend started")

    # ---------------- CAMERA ----------------

    def camera_loop(self):

        while self.running:

            ret, frame = self.cap.read()

            if not ret:
                self.get_logger().error("Camera frame failed")
                time.sleep(0.1)
                continue

            # ---------------- NORMAL CAMERA ----------------

            success, normal_buffer = cv2.imencode(
                ".jpg",
                frame,
                [cv2.IMWRITE_JPEG_QUALITY, 70]
            )

            if not success:
                continue

            normal_bytes = b"N" + normal_buffer.tobytes()

            # ---------------- AI CAMERA ----------------

            results = self.model(
                frame,
                conf=0.2,
                imgsz=640,
                verbose=False
            )

            annotated_frame = results[0].plot()

            success, ai_buffer = cv2.imencode(
                ".jpg",
                annotated_frame,
                [cv2.IMWRITE_JPEG_QUALITY, 70]
            )

            if not success:
                continue

            ai_bytes = b"A" + ai_buffer.tobytes()

            # ---------------- SEND TO REACT ----------------

            if self.loop is not None and self.websocket_clients:

                asyncio.run_coroutine_threadsafe(
                    self.send_camera(normal_bytes, ai_bytes),
                    self.loop
                )

    async def send_camera(self, normal_frame, ai_frame):

        dead_clients = set()

        for client in self.websocket_clients:

            try:
                await client.send(normal_frame)
                await client.send(ai_frame)

            except Exception:
                dead_clients.add(client)

        for client in dead_clients:
            self.websocket_clients.discard(client)

    # ---------------- SENSOR ----------------

    def receive_sensor_data(self, message):

        temperature, distance = map(
            int,
            message.data.split(",")
        )

        if temperature > 35:
            warning = "HIGH TEMPERATURE"

        elif distance < 20:
            warning = "TOO CLOSE"

        else:
            warning = "SAFE"

        data = {
            "type": "sensor",
            "temperature": temperature,
            "distance": distance,
            "warning": warning
        }

        self.get_logger().info(
            f"Sensor: {data}"
        )

        if self.loop is not None:

            asyncio.run_coroutine_threadsafe(
                self.send_sensor(data),
                self.loop
            )

    async def send_sensor(self, data):

        message = json.dumps(data)

        dead_clients = set()

        for client in self.websocket_clients:

            try:
                await client.send(message)

            except Exception:
                dead_clients.add(client)

        for client in dead_clients:
            self.websocket_clients.discard(client)

    # ---------------- ROBOT COMMAND ----------------

    def receive_command(self, command):

        message = String()

        message.data = command

        self.command_publisher.publish(message)

        self.get_logger().info(
            f"Command: {command}"
        )

    # ---------------- WEBSOCKET ----------------

    async def websocket_handler(self, websocket):

        self.websocket_clients.add(websocket)

        self.get_logger().info(
            "React connected"
        )

        try:

            async for message in websocket:

                data = json.loads(message)

                if data.get("type") == "command":

                    self.receive_command(
                        data.get("command")
                    )

        except websockets.ConnectionClosed:
            pass

        finally:

            self.websocket_clients.discard(
                websocket
            )

            self.get_logger().info(
                "React disconnected"
            )

    async def websocket_server(self):

        self.loop = asyncio.get_running_loop()

        async with websockets.serve(
            self.websocket_handler,
            "localhost",
            8080
        ):

            self.get_logger().info(
                "WebSocket server running on port 8080"
            )

            await asyncio.Future()


def start_websocket_server(node):

    asyncio.run(
        node.websocket_server()
    )


def main():

    rclpy.init()

    node = Backend()

    websocket_thread = threading.Thread(
        target=start_websocket_server,
        args=(node,),
        daemon=True
    )

    websocket_thread.start()

    rclpy.spin(node)

    node.running = False

    node.cap.release()

    node.destroy_node()

    rclpy.shutdown()


if __name__ == "__main__":
    main()